@router.get('/api/cached-reports/{report_key}')
async def get_cached_report(
    report_key: str,
    redis_conn: aioredis.Redis = Depends(get_redis),
    current_user: User = Depends(get_current_user)
):
    cached_data = await redis_conn.get(f"report:{report_key}")
    if not cached_data:
        raise HTTPException(status_code=404, detail="Report not available in cache")

    report = json.loads(cached_data)
    if report.get("org_id") != current_user.organization_id:
        raise HTTPException(status_code=403, detail="Access denied to report")

    return report
